/* The feature gate must not increase the specificity of the legacy shimmer rules. */
.interactive-session .interactive-response:where(:not(.chat-persistent-progress)) .value .chat-thinking-box.chat-thinking-active.chat-used-context-collapsed > .chat-used-context-label .monaco-button.monaco-icon-button .chat-thinking-title-shimmer,
.interactive-session .interactive-response:where(:not(.chat-persistent-progress)) .value .chat-thinking-box .chat-thinking-spinner-item .chat-thinking-spinner-label {
	background: linear-gradient(90deg,
			var(--vscode-descriptionForeground) 0%,
			var(--vscode-descriptionForeground) 30%,
			var(--vscode-chat-thinkingShimmer) 50%,
			var(--vscode-descriptionForeground) 70%,
			var(--vscode-descriptionForeground) 100%);
	background-size: 400% 100%;
	background-clip: text;
	-webkit-background-clip: text;
	-webkit-text-fill-color: transparent;
	animation: chat-thinking-shimmer 2s linear infinite;
	will-change: background-position;
}

/* Only while the footer owns progress: a background subagent can keep working after its parent
	response completes, and then its own working row is the only indicator left. */
.interactive-session .interactive-response.chat-persistent-progress.chat-response-loading .value .chat-thinking-box .chat-thinking-spinner-item {
	display: none;
}

/* Keep transcript gutter icons out of other hosts, such as the input's confirmation carousel. */
