	--chat-chain-icon-end: calc(var(--chat-chain-icon-top) + var(--vscode-codiconFontSize-compact) + var(--vscode-spacing-size40) - var(--chat-chain-rail-top, 0px));

	/* Borders keep straight and curved strokes equally crisp at fractional zoom. */
