.interactive-session .interactive-response.chat-persistent-progress > .value {
	--chat-persistent-item-gap: var(--vscode-spacing-size160);
	--chat-persistent-nested-indent: var(--vscode-spacing-size160);
	--chat-persistent-nested-gap: var(--vscode-spacing-size60);
	--chat-persistent-icon-top: calc((var(--vscode-chat-font-size-body-m) * 1.5 - var(--vscode-codiconFontSize-compact)) / 2);
	--chat-persistent-rail-left: calc(var(--vscode-codiconFontSize-compact) * 0.7 - var(--vscode-strokeThickness) / 2);
	--chat-persistent-hook-width: calc(var(--chat-persistent-nested-indent) - var(--vscode-codiconFontSize-compact) / 2 - var(--vscode-spacing-size40) + var(--vscode-strokeThickness) / 2);
}

/* The row container class keeps these ahead of the legacy `.interactive-item-container .value > …`
	spacing rules, which otherwise tie on specificity and fall back to stylesheet order. */
.interactive-session .interactive-item-container.interactive-response.chat-persistent-progress :is(.value, .completed-response-disclosure) {
	> .completed-response-disclosure,
	> .chat-tool-chain,
	> .chat-persistent-reasoning,
	> .chat-tool-call-with-icon,
	> .progress-container,
	> .chat-markdown-part,
	> .chat-confirmation-widget-container,
	> .chat-question-carousel-container,
	> .chat-mcp-servers-interaction {
		margin-block: 0 var(--chat-persistent-item-gap);

		&:last-child {
			margin-bottom: 0;
		}
	}

	> .chat-tool-call-with-icon,
	> .progress-container {
		padding-block: 0;
	}

	> .chat-persistent-reasoning,
	> .chat-tool-chain-collapsible,
	.chat-tool-chain .chat-thinking-tool-wrapper > .chat-used-context,
	.chat-tool-call-with-icon :is(.chat-terminal-thinking-collapsible, .chat-confirmation-widget-collapsible) {
		gap: 0;

		> .chat-used-context-label .monaco-button.monaco-icon-button,
		> .chat-confirmation-widget-title.monaco-button {
			padding-block: var(--vscode-spacing-size40);
			vertical-align: top;
			/* Preserve the padded hit target without adding a second visual gap. */
			margin-block: calc(-1 * var(--vscode-spacing-size40));
		}

		/* Chromium builds disagree on whether the label's line box honors the header line height
			over its smaller inline text, so give the text that line height directly. */
		> .chat-confirmation-widget-title.monaco-button .rendered-markdown {
			line-height: inherit;
		}
	}

	> :is(.chat-persistent-reasoning, .chat-tool-chain-collapsible) > .chat-used-context-label .monaco-button.monaco-icon-button {
		margin-left: calc(-1 * var(--vscode-spacing-size20));
		gap: 0;
	}

	.chat-tool-call-with-icon .chat-terminal-thinking-collapsible {
		margin-block: 0;

		> .chat-used-context-label .monaco-button-mdlabel code {
			line-height: 1;
		}
	}

	> .chat-markdown-part {
		> p {
			margin-block: 0 var(--chat-persistent-item-gap);
		}

		> :first-child {
			margin-top: 0;
		}

		> :last-child {
			margin-bottom: 0;
		}
	}

	> .chat-working-progress {
		gap: 0;
		line-height: 1.5em;
	}

	.chat-tool-call-with-icon .progress-container {
		margin-block: 0;
		padding-block: 0;
	}
}

.interactive-session .interactive-response .value .chat-thinking-box:is(.chat-persistent-reasoning, .chat-tool-chain-collapsible) > .chat-used-context-label .monaco-button.monaco-icon-button > :is(.codicon-thinking, .codicon-tools) {
