/* Reserve the tool text gutter without shifting the leading icons. */
.interactive-session .interactive-response.chat-persistent-progress > .value > .chat-working-progress > .chat-progress-icon,
.interactive-session .interactive-response .value .chat-thinking-box:is(.chat-persistent-reasoning, .chat-tool-chain-collapsible) > .chat-used-context-label .monaco-button.monaco-icon-button > :is(.codicon-thinking, .codicon-tools) {
	margin-right: calc(var(--vscode-spacing-size240) - var(--vscode-codiconFontSize-compact) - 0.2em);
}

.interactive-session .interactive-response .value .chat-thinking-box {
	outline: none;
	position: relative;
	color: var(--vscode-descriptionForeground);

	contain: layout style;

	.chat-thinking-external-resources {
		margin-top: 4px;
		margin-left: 5px;
	}

	.chat-used-context {
		margin: 0px;
	}

	> .chat-used-context-label {
		position: relative;

		&.chat-thinking-title-with-diff {
			display: flex;
			align-items: center;

			> .monaco-button.monaco-icon-button {
				min-width: 0;
				padding-right: var(--vscode-spacing-size20);
			}
		}
	}

	> .chat-used-context-label .monaco-button.monaco-icon-button {
		display: inline-flex;
		align-items: center;
		line-height: 1.5em;
		font-size: var(--vscode-chat-font-size-body-m);

		.monaco-button-mdlabel {
			font-size: var(--vscode-chat-font-size-body-s);
		}

		.codicon {
			font-size: var(--vscode-codiconFontSize-compact);
		}

		.chat-thinking-title-detail-text {
			opacity: 0.7;
		}
	}

	> .chat-used-context-label .rendered-markdown.collapsible-title-content {
		line-height: unset;
	}

	> .chat-used-context-label .rendered-markdown.chat-thinking-title-detail {
		display: inline;
		font-size: inherit;
		line-height: inherit;

		> p {
			display: inline;
			margin: 0;
		}
	}

	> .chat-used-context-label > .rendered-markdown.chat-thinking-title-detail {
		cursor: pointer;
	}

	> .chat-used-context-label > .chat-collapsible-hover-chevron {
		vertical-align: middle;
	}

	> .chat-used-context-label:hover > .chat-collapsible-hover-chevron {
		opacity: 1;
	}

	&.chat-thinking-active > .chat-used-context-label .monaco-button.monaco-icon-button {

		.codicon.codicon-circle-filled-compact {
			display: none;
		}
	}

	&:not(.chat-used-context-collapsed) .chat-used-context-list.chat-thinking-collapsible {
		overflow: visible;
		max-height: none;
	}

	/* Curved connector from the header to the first thinking item */
	&:not(.chat-used-context-collapsed) > .chat-used-context-label::after {
		content: '';
		position: absolute;
		left: 3px;
		top: 100%;
		height: 16px;
		width: 5px;
		border-left: 1px solid var(--vscode-chat-requestBorder);
		border-bottom: 1px solid var(--vscode-chat-requestBorder);
		border-bottom-left-radius: 5px;
	}

	.monaco-button.hidden,
	.chat-pinned-preview.hidden {
		display: none;
	}

	.chat-used-context-list.chat-thinking-collapsible {
		border: none;
		border-radius: 0;
		margin-bottom: 0;
		position: relative;
		overflow: hidden;
		padding-top: 0;
		margin-left: 5px;

		.chat-tool-invocation-part {
			padding: 4px 12px 4px 18px;
			position: relative;
		}

		.chat-thinking-tool-wrapper {
			.chat-used-context {
				margin-bottom: 0px;
				margin-left: 4px;
				padding-left: 2px;

				.monaco-button.monaco-text-button {
					color: var(--vscode-descriptionForeground);
					display: flex;
					align-items: center;

					:hover {
						color: var(--vscode-foreground);
					}

					.monaco-button:hover .chat-collapsible-hover-chevron {
						opacity: 1;
					}
				}
			}

			.chat-used-context:not(.chat-used-context-collapsed) {
				.monaco-button.monaco-text-button {
					color: var(--vscode-foreground);
				}
			}

			.progress-container,
			.chat-confirmation-widget-container {
				margin: 0 0 0 6px;
				box-sizing: border-box;
				max-width: calc(100% - 6px);
			}

			/* todo: ideally not !important, but the competing css has 14 specificity */
			.codicon.codicon-check-compact,
			.codicon.codicon-loading-compact {
				display: none !important;
			}

			.chat-collapsible-hover-chevron.codicon {
				display: inline-flex;
			}

			.show-checkmarks .chat-confirmation-widget-title > .codicon:first-child:not(.chat-collapsible-hover-chevron) {
				display: inline-block;
			}

			.show-checkmarks .progress-container > .codicon.codicon-check-compact {
				display: inline-flex;
			}

			.chat-used-context.chat-hook-outcome-blocked,
			.chat-used-context.chat-hook-outcome-warning {
				padding: 4px 12px 4px 20px;
				margin-bottom: 0;
			}
		}

		.chat-thinking-item.markdown-content {
			padding: 6px 12px 6px 24px;
			position: relative;
			font-size: var(--vscode-chat-font-size-body-s);

			.progress-container {
				margin-bottom: 0px;
				padding-top: 0px;
			}

			[data-code] {
				background-color: var(--vscode-textPreformat-background);
				padding: 1px 3px;
				border-radius: 4px;
				border: 1px solid var(--vscode-textPreformat-border);
				white-space: pre-wrap;
			}
		}

		.chat-thinking-tool-wrapper .chat-markdown-part.rendered-markdown {
			padding: 5px 12px 4px 24px;

			.status-icon.codicon-check-compact {
				display: none;
			}

			.show-checkmarks .status-icon.codicon-check-compact {
				display: inline-flex;
			}

			.code:has(.chat-codeblock-pill-container) {
				margin-bottom: 0px;

				.chat-codeblock-pill-container {
					margin-bottom: 0px;
				}
			}
		}

		/*
		 * External-edit pills (agent host) sit directly inside
		 * `.chat-thinking-tool-wrapper` rather than nested inside a markdown
		 * code block, so they need the same left padding to clear the
		 * absolutely-positioned thinking icon.
		 */
		.chat-thinking-tool-wrapper > .chat-codeblock-pill-container {
			padding: 5px 12px 4px 24px;

			.status-icon.codicon-check-compact {
				display: none;
			}

			.show-checkmarks .status-icon.codicon-check-compact {
				display: inline-flex;
			}
		}

		.chat-confirmation-widget2 .chat-confirmation-message-terminal-disclaimer .chat-markdown-part.rendered-markdown {
			padding: 2px 0px;
		}

		.chat-thinking-tool-wrapper .chat-terminal-thinking-content .chat-markdown-part.rendered-markdown {
			padding: 0;
		}

		/* chain of thought lines */
		.chat-thinking-tool-wrapper,
		.chat-thinking-item.markdown-content,
		.chat-thinking-spinner-item {
			position: relative;

			&::before {
				content: '';
				position: absolute;
				left: 10.5px;
				top: 0px;
				bottom: 0px;
				width: 1px;
				border-radius: 0;
				background-color: var(--vscode-chat-requestBorder);
				mask-image: linear-gradient(to bottom, #000 0 5px, transparent 5px 25px, #000 24px 100%);
			}

			&:first-child::before {
				mask-image: linear-gradient(to bottom, transparent 0 25px, #000 25px 100%);
			}

			&:last-child::before {
				mask-image: linear-gradient(to bottom, #000 0 5px, transparent 5px 100%);
			}

			&:only-child::before {
				background: none;
				mask-image: none;
			}

			> .chat-thinking-icon {
				position: absolute;
				left: 5px;
				top: 9px;
				width: 12px;
				height: 12px;
				font-size: var(--vscode-codiconFontSize-compact);
				line-height: 12px;
				text-align: center;
				color: var(--vscode-descriptionForeground);
			}

			/* the default book icon has a pixel of space at the bottom */
			> .chat-thinking-icon .codicon.codicon-book {
				top: 10px;
			}
		}

		.chat-thinking-spinner-item {
			padding: 6px 12px 6px 24px;
			font-size: var(--vscode-chat-font-size-body-s);

			.chat-thinking-spinner-label {
				color: var(--vscode-descriptionForeground);
			}
		}
	}

	.chat-thinking-item {
		padding: 6px 12px;
		position: relative;

		.progress-container {
			margin-bottom: 0px;
			padding-top: 0px;
		}
	}

	.chat-thinking-text {
		font-size: var(--vscode-chat-font-size-body-s);
		padding: 0 10px;
		display: block;
	}

	.rendered-markdown > p {
		margin: 0;

		& + p {
			margin-top: 5px;
		}
	}
}

