	}
}

.interactive-session .interactive-response .value .chat-thinking-fixed-mode {
	outline: none;

	/* Hide the header/collapse button while streaming — it reappears when chat-thinking-streaming is removed */
	&:has(.chat-thinking-streaming) > .chat-used-context-label {
		display: none;
	}

	> .monaco-scrollable-element > .shadow {
		display: none;
	}

	/* Directional fade indicators via mask-image on the scrollable viewport */
	&.chat-thinking-fade-top > .monaco-scrollable-element {
		mask-image: linear-gradient(to bottom, transparent 0px, black 20px);
		-webkit-mask-image: linear-gradient(to bottom, transparent 0px, black 20px);
	}

	&.chat-thinking-fade-bottom > .monaco-scrollable-element {
		mask-image: linear-gradient(to top, transparent 0px, black 20px);
		-webkit-mask-image: linear-gradient(to top, transparent 0px, black 20px);
	}

	&.chat-thinking-fade-top.chat-thinking-fade-bottom > .monaco-scrollable-element {
		mask-image: linear-gradient(to bottom, transparent 0px, black 20px, black calc(100% - 20px), transparent 100%);
		-webkit-mask-image: linear-gradient(to bottom, transparent 0px, black 20px, black calc(100% - 20px), transparent 100%);
	}

	> .monaco-scrollable-element:has(.chat-used-context-list.chat-thinking-collapsible:not(.chat-thinking-streaming)) {
		overflow: hidden;
		height: auto;
		opacity: 1;

		> .scrollbar {
			display: none;
		}
	}

	&.chat-thinking-fixed-mode-animated > .monaco-scrollable-element {
		transition:
			max-height 180ms cubic-bezier(0.2, 0, 0, 1),
			opacity 140ms cubic-bezier(0.2, 0, 0, 1);
	}

	&.chat-used-context-collapsed > .monaco-scrollable-element:has(.chat-used-context-list.chat-thinking-collapsible:not(.chat-thinking-streaming)) {
		display: block;
		opacity: 0;

		> .chat-used-context-list.chat-thinking-collapsible {
			display: block;
		}
	}

	&.chat-used-context-collapsed .chat-used-context-list.chat-thinking-collapsible.chat-thinking-streaming {
		max-height: 200px;
		overflow: hidden;
		display: block;
		margin-left: 0px;
		padding-left: 0px;

		.chat-tool-invocation-part {
			padding-left: 13px;
		}

		.chat-thinking-spinner-item {
			padding-left: 19px;
		}

		.chat-used-context.chat-hook-outcome-blocked,
		.chat-used-context.chat-hook-outcome-warning {
			padding-left: 15px;
		}

		.chat-thinking-item.markdown-content {
			padding-left: 19px;
		}

		.chat-thinking-tool-wrapper .chat-markdown-part.rendered-markdown {
			padding-left: 19px;
		}

		.chat-thinking-tool-wrapper > .chat-codeblock-pill-container {
			padding-left: 19px;
		}

		/* chain of thought lines */
		.chat-thinking-tool-wrapper,
		.chat-thinking-item.markdown-content,
		.chat-thinking-spinner-item {
			&::before {
				left: 5.5px;
			}

			> .chat-thinking-icon {
				left: 0px;
			}
		}
	}

	&:not(.chat-used-context-collapsed) .chat-used-context-list.chat-thinking-collapsible.chat-thinking-streaming {
		max-height: none;
		overflow: visible;
		display: block;
	}

	&:not(.chat-used-context-collapsed) > .monaco-scrollable-element:has(.chat-thinking-streaming) {
		overflow: visible;
		height: auto;
	}

	.chat-used-context-list.chat-thinking-collapsible:not(.chat-thinking-streaming) {
		max-height: none;
		overflow: visible;
	}

	.chat-thinking-tool-wrapper .chat-used-context:not(.chat-used-context-collapsed) .chat-used-context-list {
		display: block;
	}
}

.editor-instance .interactive-session .interactive-response .value .chat-thinking-box .chat-thinking-item ::before {
	background: var(--vscode-editor-background);
}

.monaco-reduce-motion .chat-thinking-fixed-mode > .monaco-scrollable-element,
.monaco-workbench.monaco-reduce-motion .chat-thinking-fixed-mode > .monaco-scrollable-element {
	transition: none !important;
}

@media (prefers-reduced-motion: reduce) {
	.chat-thinking-fixed-mode > .monaco-scrollable-element {
		transition: none !important;
	}
}

.interactive-session .interactive-response .value .chat-thinking-box .chat-used-context-label code {
	display: inline;
	line-height: inherit;
	padding: 1px 3px;
}
